SELECT c.*, up.nickname AS account_name, up.avatar_url AS account_avatar
FROM comment c LEFT JOIN user_profile up ON c.account_id = up.account_id
WHERE c.target_type = #{targetType} AND c.target_id = #{targetId}
ORDER BY c.create_time DESC LIMIT #{offset}, #{limit}

SELECT c.*, up.nickname AS account_name, up.avatar_url AS account_avatar
FROM comment c LEFT JOIN user_profile up ON c.account_id = up.account_id
WHERE c.account_id = #{accountId}
ORDER BY c.create_time DESC LIMIT #{offset}, #{limit}

